#!/usr/bin/env python3
"""Agenda Clara 2.6: install timetable, offline OCR and weekly notifications into 2.5 sources.
Run from the project-parent directory (containing AgendaClara/).
"""
from pathlib import Path
import base64,zlib,json
src=Path('AgendaClara/app/src/main/java/pe/agendaclara/app')
files=json.loads(zlib.decompress(base64.b64decode('')).decode('utf-8'))
for name,source in files.items():
    if not name.startswith('Schedule') or not name.endswith('.java'):raise ValueError(name)
    (src/name).write_text(source,encoding='utf-8')
def replace(path,old,new):
    s=path.read_text(encoding='utf-8').replace('\x00','\\0')
    if s.count(old)!=1:raise RuntimeError(f'Expected one insertion anchor in {path}: {old[:80]}')
    path.write_text(s.replace(old,new,1),encoding='utf-8')
project=Path('AgendaClara')
gradle=project/'app/build.gradle'
replace(gradle,"versionCode 14\n        versionName '2.5.0'","versionCode 15\n        versionName '2.6.0'")
with gradle.open('a',encoding='utf-8') as output:
    output.write("\n// Offline OCR model bundled with the APK.\ndependencies { implementation 'com.google.mlkit:text-recognition:16.0.1' }\n")
manifest=project/'app/src/main/AndroidManifest.xml'
replace(manifest,'        <activity android:name=".ComposeDayActivity"','''        <provider android:name="androidx.core.content.FileProvider" android:authorities="${applicationId}.schedule_provider" android:exported="false" android:grantUriPermissions="true">
            <meta-data android:name="android.support.FILE_PROVIDER_PATHS" android:resource="@xml/schedule_file_paths" />
        </provider>
        <activity android:name=".ScheduleActivity" android:exported="false" android:theme="@style/AppTheme" android:windowSoftInputMode="adjustResize" />
        <receiver android:name=".ScheduleAlarmReceiver" android:exported="false" />
        <activity android:name=".ComposeDayActivity"''')
(project/'app/src/main/res/xml/schedule_file_paths.xml').write_text('''<?xml version="1.0" encoding="utf-8"?>
<paths xmlns:android="http://schemas.android.com/apk/res/android"><cache-path name="schedule_images" path="schedule_images/" /></paths>
''',encoding='utf-8')
main=src/'MainActivity.java'
replace(main,'    void calendarPage(){\n        List<Task> all=Store.get(this).all();','''    void calendarPage(){
        LinearLayout schedule=card(body);
        schedule.addView(text("▦  Horario de clases",20,INK,true));gap(schedule,6);
        schedule.addView(text("Organiza tus cursos por semana, importa una foto y recibe avisos antes de cada clase.",13,MUTED,false));gap(schedule,12);
        schedule.addView(primaryButton("Abrir mi horario  →",()->startActivity(new Intent(this,ScheduleActivity.class))));
        List<Task> all=Store.get(this).all();''')
replace(src/'SystemReceiver.java','Reminders.rebuild(c);TaskWidget.refresh(c);','Reminders.rebuild(c);ScheduleReminders.rebuild(c);TaskWidget.refresh(c);')
print('Agenda Clara 2.6 timetable feature installed into native project.')